def transform(n,objs,blank):
    base=[[0]*n for _ in range(n)]; cells={}
    for idx,(r,c,v) in enumerate(objs):
        base[r][c]=v; cells[(r,c)]=idx
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:base[r+dr][c+dc]=3;cells[(r+dr,c+dc)]=idx
    br,bc=blank
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:base[br+dr][bc+dc]=3;cells[(br+dr,bc+dc)]=len(objs)
    vert=[[0]*n for _ in range(n)];horiz=[[0]*n for _ in range(n)]
    for idx,(r,c,v) in enumerate(objs):
        for dr,dc,target in [(1,0,vert),(-1,0,vert),(0,1,horiz),(0,-1,horiz)]:
            rr,cc=r+dr,c+dc
            while 0<=rr<n and 0<=cc<n:
                owner=cells.get((rr,cc))
                if owner is not None and owner!=idx and owner<len(objs): break
                if base[rr][cc]==0 and (target is vert or cc!=bc):target[rr][cc]=v
                rr+=dr;cc+=dc
    out=[[base[i][j] or vert[i][j] or horiz[i][j] for j in range(n)] for i in range(n)]
    return out
